import pathlib,json,subprocess,shlex,hashlib,statistics
A=pathlib.Path(__file__).resolve().parent;R=A.parent
records=[]
def run(name,args,cwd=R):
 p=subprocess.run(args,cwd=cwd,text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT);(A/(name+'.log')).write_text(p.stdout);records.append(dict(name=name,args=args,exit_code=p.returncode));(A/'verification_commands.json').write_text(json.dumps(records,indent=2));return p
B=A/'build-release';cs=json.loads((B/'compile_commands.json').read_text());c=next(c for c in cs if c['file'].endswith('/selective_recovery_tests.cpp'))
s=(R/'tests/selective_recovery_tests.cpp').read_text().replace('ASSERT_EQ(res.status,','ASSERT_TRUE(false, "audit intentional failure in copied source");\n    ASSERT_EQ(res.status,',1);(A/'assertion_probe.cpp').write_text(s)
args=shlex.split(c['command']);args[args.index('-o')+1]=str(A/'assertion_probe.o');args[-1]=str(A/'assertion_probe.cpp');run('assertion-compile',args)
link=shlex.split((B/'CMakeFiles/rbl_selective_recovery_tests.dir/link.txt').read_text());link=[str(A/'assertion_probe.o') if x.endswith('selective_recovery_tests.cpp.o') else str(B/x) if x in ['librbl_engine.a','libanytime_mapf_core.a'] else x for x in link];link[link.index('-o')+1]=str(A/'assertion_probe');run('assertion-link',link);run('assertion-expected-failure',[str(A/'assertion_probe'),'data/sample/random-32-32-20.map','data/sample/random-32-32-20-random-1.scen'])
run('unsupported-sanitizer-option',['cmake','-S',str(R),'-B',str(A/'build-option-check'),'-DCMAKE_BUILD_TYPE=Debug','-DENABLE_SANITIZERS=ON','-DCMAKE_CXX_COMPILER=/Library/Developer/CommandLineTools/usr/bin/clang++','-DCMAKE_OSX_SYSROOT=/Library/Developer/CommandLineTools/SDKs/MacOSX.sdk'])
run('git-root',['git','rev-parse','--show-toplevel']);run('git-branch',['git','branch','--show-current']);run('git-head',['git','rev-parse','HEAD'])
run('historical-behavior-diff',['git','diff','b4d9f9e','07973d0','--','src','CMakeLists.txt'])
run('baseline-changes',['git','show','b4d9f9e','--','src','CMakeLists.txt'])
r=json.loads((R/'results/partial_acceptance_pilot/all_runs.json').read_text());ex=[x for x in r if x['policy']=='EXACT_PARTIAL_ACCEPTANCE'];print('historical',len(r),len(ex),'median of medians',statistics.median(x['pa_telemetry']['total_pa_overhead_us']['median'] for x in ex),'pa total',sum(x['pa_total_time_us'] for x in ex),'share',100*sum(x['pa_total_time_us'] for x in ex)/1e6/sum(x['total_solve_time_s'] for x in ex))
snaps=[s for p in (R/'results/partial_acceptance_offline/raw').glob('*.json') for s in json.loads(p.read_text())['snapshots']];print('offline selected negative',[(s['exact_gain'],s['nonnegative_ref_gain']) for s in snaps if s['exact_selected_negative_count']]);print('total exact minus reference',sum(s['exact_gain']-s['nonnegative_ref_gain'] for s in snaps))
(A/'additional_raw_checks.log').write_text('Historical exact: '+json.dumps({'runs':len(ex),'median_of_run_medians_us':statistics.median(x['pa_telemetry']['total_pa_overhead_us']['median'] for x in ex),'total_pa_us':sum(x['pa_total_time_us'] for x in ex),'share_pct':100*sum(x['pa_total_time_us'] for x in ex)/1e6/sum(x['total_solve_time_s'] for x in ex)})+'\nSelected-negative snapshots: '+str([(s['exact_gain'],s['nonnegative_ref_gain']) for s in snaps if s['exact_selected_negative_count']])+'\nAll snapshots exact minus reference: '+str(sum(s['exact_gain']-s['nonnegative_ref_gain'] for s in snaps)))
